typedef long long ll;

static ll gcdll(ll a, ll b) {
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a >= 0 ? a : -a;
}

int main(void) {
    ll W, H, K;
    if (scanf("%lld %lld %lld", &W, &H, &K) != 3) return 0;

    /* We count triangles whose three vertices lie on three different sides
       of the rectangle, and none is a rectangle vertex.

       Any valid triangle must use one side from each of two opposite pairs:
       either {top,bottom,left/right} or {left,right,top/bottom}.
       Equivalently, there are 4 corner-missing configurations:
         bottom+left+top, bottom+left+right, bottom+right+top, left+top+right.
       By symmetry:
         count(bottom,left,top) = count(bottom,right,top)
         count(bottom,left,right) = count(left,top,right)
       So total = 2*A + 2*B where
         A = count of triangles with vertices on bottom, left, top
         B = count of triangles with vertices on bottom, left, right
       excluding rectangle corners.

       For A:
         vertices are (x,0), (0,y), (u,H)
         with 1<=x<=W-1, 1<=y<=H-1, 1<=u<=W-1.
         Area2 = x(H-y) + uy.
         Boundary points on edges:
           gcd(x,y) + gcd(u,H-y) + gcd(u-x,H)
         Interior by Pick:
           I = (Area2 - B + 2)/2
       Need I <= K.

       For B:
         vertices are (x,0), (0,y), (W,v)
         with 1<=x<=W-1, 1<=y<=H-1, 1<=v<=H-1.
         Area2 = Wy + xv - xH.
         Taking absolute value gives positive:
           Area2 = Wy + x(v-y)
         but easier via shoelace:
           |x(y-v)+Wy| = Wy + x(v-y) since geometry gives positive.
         Boundary:
           gcd(x,y) + gcd(W,y-v) + gcd(W-x,v)
         Interior similarly.

       Constraints are not provided in the statement here; we use O(W^2 H + W H^2),
       which is acceptable for moderate limits typical of this task.
    */

    ll total = 0;

    /* A: bottom, left, top */
    ll A = 0;
    for (ll x = 1; x <= W - 1; ++x) {
        for (ll y = 1; y <= H - 1; ++y) {
            ll g1 = gcdll(x, y);
            for (ll u = 1; u <= W - 1; ++u) {
                ll area2 = x * (H - y) + u * y;
                ll Bnd = g1 + gcdll(u, H - y) + gcdll(llabs(u - x), H);
                ll I2 = area2 - Bnd + 2; /* = 2*I */
                if (I2 <= 2 * K) A++;
            }
        }
    }

    /* B: bottom, left, right */
    ll B = 0;
    for (ll x = 1; x <= W - 1; ++x) {
        for (ll y = 1; y <= H - 1; ++y) {
            ll g1 = gcdll(x, y);
            for (ll v = 1; v <= H - 1; ++v) {
                ll area2 = W * y + x * (v - y);
                if (area2 < 0) area2 = -area2;
                ll Bnd = g1 + gcdll(W, llabs(y - v)) + gcdll(W - x, v);
                ll I2 = area2 - Bnd + 2;
                if (I2 <= 2 * K) B++;
            }
        }
    }

    total = 2 * A + 2 * B;
    printf("%lld\n", total);
    return 0;
}

