#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

static inline int64 gcdll(int64 a, int64 b) {
    while (b) {
        int64 t = a % b;
        a = b;
        b = t;
    }
    return a >= 0 ? a : -a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 W, H, K;
    cin >> W >> H >> K;

    // Choose one point from each of three different sides.
    // There are 4 choices of the omitted side.
    //
    // For one fixed choice, say:
    // A = (x,0), 1<=x<=W-1   bottom
    // B = (0,y), 1<=y<=H-1   left
    // C = (u,H), 1<=u<=W-1   top
    //
    // Then:
    //   2*Area = H*(x+u)
    // Boundary lattice points on edges:
    //   gcd(x,y), gcd(u,y-H)=gcd(u,H-y), gcd(u, H?) no, BC = gcd(u, H-y), AC = gcd(|u-x|, H)
    // More directly for this orientation:
    //   Bnd = gcd(x,y) + gcd(u, H-y) + gcd(abs(u-x), H)
    // Interior by Pick:
    //   I = (2A - Bnd + 2)/2
    //
    // We need count of triples with I <= K.
    //
    // By symmetry, all 4 omitted-side choices have the same count, so multiply by 4.

    int64 ans_one = 0;

    for (int64 x = 1; x <= W - 1; ++x) {
        for (int64 u = 1; u <= W - 1; ++u) {
            int64 area2 = H * (x + u);
            int64 g3 = gcdll(llabs(u - x), H);

            for (int64 y = 1; y <= H - 1; ++y) {
                int64 g1 = gcdll(x, y);
                int64 g2 = gcdll(u, H - y);
                int64 B = g1 + g2 + g3;
                int64 I = (area2 - B + 2) / 2;
                if (I <= K) ++ans_one;
            }
        }
    }

    int64 ans = ans_one * 4;
    cout << ans << '\n';
    return 0;
}

