public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int W = sc.nextInt();
        int H = sc.nextInt();
        int K = sc.nextInt();
        long count = 0;

        // Choose which side is omitted: 0=bottom,1=top,2=left,3=right
        // We'll generate triples of sides

        // Omit bottom: sides top, left, right
        for (int y = 1; y < H; y++) { // left side (0,y)
            for (int x = 1; x < W; x++) { // top side (x,H)
                for (int w = 1; w < W; w++) { // right side (W,w)
                    if (checkTriangle(0, y, x, H, W, w, K)) count++;
                }
            }
        }

        // Omit top: sides bottom, left, right
        for (int y = 1; y < H; y++) { // left side (0,y)
            for (int x = 1; x < W; x++) { // bottom side (x,0)
                for (int w = 1; w < W; w++) { // right side (W,w)
                    if (checkTriangle(0, y, x, 0, W, w, K)) count++;
                }
            }
        }

        // Omit left: sides bottom, top, right
        for (int x1 = 1; x1 < W; x1++) { // bottom (x1,0)
            for (int x2 = 1; x2 < W; x2++) { // top (x2,H)
                for (int w = 1; w < H; w++) { // right (W,w)
                    if (checkTriangle(x1, 0, x2, H, W, w, K)) count++;
                }
            }
        }

        // Omit right: sides bottom, top, left
        for (int x1 = 1; x1 < W; x1++) { // bottom (x1,0)
            for (int x2 = 1; x2 < W; x2++) { // top (x2,H)
                for (int y = 1; y < H; y++) { // left (0,y)
                    if (checkTriangle(x1, 0, x2, H, 0, y, K)) count++;
                }
            }
        }

        System.out.println(count);
    }

    // Check triangle with vertices (x1,y1), (x2,y2), (x3,y3)
    static boolean checkTriangle(int x1, int y1, int x2, int y2, int x3, int y3, int K) {
        long area2 = Math.abs((long)(x2 - x1) * (y3 - y1) - (long)(x3 - x1) * (y2 - y1));
        long area = area2 / 2;
        long B = gcd(Math.abs(x2 - x1), Math.abs(y2 - y1))
               + gcd(Math.abs(x3 - x2), Math.abs(y3 - y2))
               + gcd(Math.abs(x1 - x3), Math.abs(y1 - y3));
        long I = area + 1 - B / 2;
        return I <= K;
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

