import java.io.*;
import java.util.*;

public class Main {
    // Count triangles with vertices on 3 different sides of rectangle [0,W] x [0,H],
    // not using rectangle corners, and with at most K interior lattice points.

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long W = fs.nextLong();
        long H = fs.nextLong();
        long K = fs.nextLong();

        // If one dimension is 1, no side has interior lattice points on both opposite pairs enough
        // to form valid triangles with all vertices on different sides excluding corners as needed.
        if (W <= 1 || H <= 1) {
            System.out.println(0);
            return;
        }

        // We count by choosing one vertical side and two horizontal sides:
        // left-bottom-top, right-bottom-top, bottom-left-right, top-left-right.
        // By symmetry:
        // total = 2 * count(left, bottom, top) + 2 * count(bottom, left, right)
        long ans1 = countType(W, H, K); // one vertical side, both horizontal sides
        long ans2 = countType(H, W, K); // one horizontal side, both vertical sides (swap roles)

        long ans = 2L * ans1 + 2L * ans2;
        System.out.println(ans);
    }

    // Count triangles with vertices:
    // A on x=0:      A=(0,a), 1<=a<=H-1
    // B on y=0:      B=(b,0), 1<=b<=W-1
    // C on y=H:      C=(c,H), 1<=c<=W-1
    //
    // Interior lattice points I satisfy by Pick:
    // 2I = area2 - boundary + 2
    // area2 = |H*(b+c) - W*a|
    // boundary = gcd(a,b) + gcd(H-a,c) + gcd(H, |c-b|)
    //
    // We need I <= K and non-collinear.
    static long countType(long W, long H, long K) {
        int wi = (int) W;
        int hi = (int) H;

        // Precompute gcd(H, d) for d in [0..W-1]
        int[] gcdHd = new int[wi];
        for (int d = 0; d < wi; d++) gcdHd[d] = gcd(hi, d);

        // Precompute gcd(a,b), 1<=a<=H-1,1<=b<=W-1
        int[][] g1 = new int[hi][wi];
        for (int a = 1; a <= hi - 1; a++) {
            for (int b = 1; b <= wi - 1; b++) {
                g1[a][b] = gcd(a, b);
            }
        }

        // Precompute gcd(H-a,c), 1<=a<=H-1,1<=c<=W-1
        int[][] g2 = new int[hi][wi];
        for (int a = 1; a <= hi - 1; a++) {
            int ha = hi - a;
            for (int c = 1; c <= wi - 1; c++) {
                g2[a][c] = gcd(ha, c);
            }
        }

        long res = 0;

        // Iterate over a and pairs (b,c)
        for (int a = 1; a <= hi - 1; a++) {
            for (int b = 1; b <= wi - 1; b++) {
                for (int c = 1; c <= wi - 1; c++) {
                    long area2 = Math.abs(H * (long)(b + c) - W * (long)a);
                    if (area2 == 0) continue; // degenerate

                    long boundary = g1[a][b] + g2[a][c] + gcdHd[Math.abs(c - b)];
                    long twoI = area2 - boundary + 2;
                    // For lattice triangle, twoI is even and >= 0
                    if (twoI <= 2L * K) res++;
                }
            }
        }

        return res;
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

