import sys
from math import gcd

def count_side_points(w, h, side):
    # Number of lattice points on a side excluding rectangle vertices
    if side in (0, 1):  # bottom or top
        return max(0, w - 1)
    else:               # left or right
        return max(0, h - 1)

def side_point_to_xy(idx, val, W, H):
    # side: 0=bottom, 1=top, 2=left, 3=right
    if idx == 0:
        return val, 0
    if idx == 1:
        return val, H
    if idx == 2:
        return 0, val
    return W, val

def interior_points_triangle(p1, p2, p3):
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = p3

    area2 = abs((x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1))  # 2*area
    b = (
        gcd(abs(x1 - x2), abs(y1 - y2)) +
        gcd(abs(x2 - x3), abs(y2 - y3)) +
        gcd(abs(x3 - x1), abs(y3 - y1))
    )
    # Pick: area = I + B/2 - 1  =>  2I = area2 - B + 2
    return (area2 - b + 2) // 2

def solve():
    data = list(map(int, sys.stdin.read().strip().split()))
    if len(data) != 3:
        return
    W, H, K = data

    # Points on each side excluding corners
    side_vals = [
        list(range(1, W)),  # bottom
        list(range(1, W)),  # top
        list(range(1, H)),  # left
        list(range(1, H)),  # right
    ]

    ans = 0

    # Choose 3 different sides out of 4
    sidesets = [
        (0, 1, 2),
        (0, 1, 3),
        (0, 2, 3),
        (1, 2, 3),
    ]

    for a, b, c in sidesets:
        for va in side_vals[a]:
            p1 = side_point_to_xy(a, va, W, H)
            for vb in side_vals[b]:
                p2 = side_point_to_xy(b, vb, W, H)
                for vc in side_vals[c]:
                    p3 = side_point_to_xy(c, vc, W, H)
                    if interior_points_triangle(p1, p2, p3) <= K:
                        ans += 1

    print(ans)

if __name__ == "__main__":
    solve()
